<?php
if(!defined('ABSPATH'))exit;
function dgs_school_url($tab,$year,$args=array()){return add_query_arg(array_merge(array('dg_tab'=>$tab,'dg_year'=>$year),$args),dgs_page_url('portal'));}
function dgs_school_form($op,$year){return '<form method="post" class="dge-form dsp-form" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_school','dgs_school_nonce',true,false).'<input type="hidden" name="action" value="dgs_school"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="year" value="'.esc_attr($year).'">';}
function dgs_school_title($title,$subtitle=''){return '<header class="dsp-heading"><h2>'.dgs_school_icon(dgs_visual_icon_name($title,'overview')).esc_html($title).'</h2>'.($subtitle?'<p>'.esc_html($subtitle).'</p>':'').'</header>';}
function dgs_school_number($value,$decimals=0){return $value===null?'—':dgs_fa_digits(number_format((float)$value,$decimals));}
function dgs_school_icon($key){if(function_exists('dgs_portal_icon'))return dgs_portal_icon($key);$paths=array('clock'=>'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v6l4 2','edit'=>'M16 3l5 5-12 12H4v-5zM14 5l5 5','class'=>'M3 4h18v12H3zM12 16v5M7 21h10','users'=>'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M19 8v6M16 11h6','chart'=>'M5 20V12M12 20V4M19 20V9','medal'=>'M8 3h8l-1 6H9zM12 10a5 5 0 1 0 0 10 5 5 0 0 0 0-10M10 20v3l2-1 2 1v-3','book'=>'M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2zM12 6v15','calendar'=>'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16M8 14h1M15 14h1M8 18h1','coin'=>'M4 5c0-4 16-4 16 0s-16 4-16 0v13c0 4 16 4 16 0V5M4 11c0 4 16 4 16 0M4 16c0 4 16 4 16 0','bell'=>'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4','check'=>'M5 12l4 4L20 5M4 3h9M3 3v18h18V11','cap'=>'M1 8l11-5 11 5-11 5zM5 11v6c4 4 10 4 14 0v-6M22 9v9');return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="'.($paths[$key]??$paths['book']).'"/></svg>';}
function dgs_school_art(){return '<svg class="dsp-welcome-art" aria-hidden="true" viewBox="0 0 260 120"><path d="M30 110C-20 50 20 25 55 105M40 105C5 10 65 10 59 100M57 105C72 40 95 60 76 110" fill="#d8c2f0"/><rect x="55" y="72" width="120" height="31" rx="12" fill="#713895"/><rect x="67" y="77" width="109" height="20" rx="8" fill="#fff0bb"/><path d="M60 103h119" stroke="#51216f" stroke-width="5"/><rect x="81" y="41" width="99" height="31" rx="11" fill="#ffd13e"/><rect x="89" y="46" width="90" height="20" rx="8" fill="#fff3cc"/><rect x="58" y="14" width="105" height="29" rx="11" fill="#a779c8"/><rect x="63" y="19" width="83" height="19" rx="7" fill="#eee2f6"/><path d="M60 15h93M62 43h91" stroke="#734294" stroke-width="4"/><path d="M198 96l-9-60M209 93l5-69M218 99l18-57" stroke="#67348b" stroke-width="8"/><path d="M210 61l4-37M227 64l9-22" stroke="#ffc526" stroke-width="7"/><path d="M184 66h51l-7 42h-37z" fill="#8d58b1"/></svg>';}
function dgs_school_stat($title,$value,$unit,$icon='chart',$gold=false){return '<article class="dsp-stat '.($gold?'is-gold':'').'"><span class="dsp-stat-icon">'.dgs_school_icon($icon).'</span><div><h3>'.esc_html($title).'</h3><strong>'.esc_html($value).'</strong><small>'.esc_html($unit).'</small></div></article>';}
function dgs_school_line_chart($series){
 if(!$series)return '<p class="dsp-empty">هنوز نمره منتشرشده‌ای ثبت نشده است.</p>';$series=array_reverse($series);$values=array_map(function($r){return (float)$r->average;},$series);$min=min($values)>=15?15:0;$width=450;$height=170;$points=array();$n=count($series);foreach($series as $i=>$r)$points[]=array('x'=>60+($n===1?180:$i*340/($n-1)),'y'=>185-(((float)$r->average-$min)/(20-$min))*140,'value'=>(float)$r->average,'label'=>$r->period);$id=wp_unique_id('dsp-chart-');$out='<svg class="dsp-line-chart" viewBox="0 0 450 245" role="img" aria-label="روند میانگین نمرات منتشرشده"><defs><linearGradient id="'.$id.'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a05ad1" stop-opacity=".4"/><stop offset="100%" stop-color="#a05ad1" stop-opacity=".03"/></linearGradient></defs>';
 for($i=0;$i<=5;$i++){$y=185-$i*28;$v=$min+(20-$min)*$i/5;$out.='<line x1="50" x2="420" y1="'.$y.'" y2="'.$y.'" stroke="#e6d8f0"/><text x="40" y="'.($y+4).'" text-anchor="end">'.esc_html(dgs_school_number($v,1)).'</text>';}$coords=implode(' ',array_map(function($p){return $p['x'].','.$p['y'];},$points));$out.='<polygon points="'.$points[0]['x'].',185 '.$coords.' '.$points[$n-1]['x'].',185" fill="url(#'.$id.')"/><polyline points="'.$coords.'" fill="none" stroke="#8528bc" stroke-width="3"/>';
 foreach($points as $i=>$p){$out.='<circle cx="'.$p['x'].'" cy="'.$p['y'].'" r="4" fill="#fff" stroke="#8528bc" stroke-width="3"/><rect x="'.($p['x']-26).'" y="'.($p['y']-29).'" width="52" height="22" rx="8" fill="'.($i===$n-1?'#ffe48c':'#f8f1ff').'"/><text x="'.$p['x'].'" y="'.($p['y']-14).'" text-anchor="middle" class="dsp-chart-value">'.esc_html(dgs_school_number($p['value'],2)).'</text><text x="'.$p['x'].'" y="218" text-anchor="middle">'.esc_html(dgs_fa_digits($p['label'])).'</text>';}
 return $out.'</svg><p class="dsp-footnote">میانگین ساده نمرات منتشرشده هر ماه؛ معدل رسمی نوبت نیست.</p>';
}
function dgs_school_ring($percent,$label,$class=''){return '<div class="dsp-ring '.esc_attr($class).'" style="--dsp-value:'.($percent===null?0:max(0,min(100,(float)$percent))).'%"><div><strong>'.esc_html($percent===null?'—':dgs_school_number($percent,1).'٪').'</strong><small>'.esc_html($label).'</small></div></div>';}
function dgs_school_student_dashboard($year){
 if(!dgs_edu_role(get_current_user_id(),'dgs_student'))return '';$uid=get_current_user_id();$u=wp_get_current_user();$class=dgs_hw_student_class($year);$series=dgs_school_grade_series($year,$uid);$average=$series?(float)$series[0]->average:null;$rank=null;global $wpdb;$e=dgs_edu_tables();$g=dgs_grade_table();$h=dgs_hw_tables();
 if($class&&$series)$rank=1+(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM (SELECT x.student_id,AVG(x.score) AS av FROM $g x JOIN {$e['classes']} c ON c.id=x.class_id WHERE c.school_year=%s AND c.grade=%d AND x.period=%s AND x.published=1 GROUP BY x.student_id HAVING AVG(x.score)>%f) ranked",$year,$class->grade,$series[0]->period,$average+0.00001));
 $pending=$class?(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$h['tasks']} a WHERE a.class_id=%d AND a.school_year=%s AND a.active=1 AND (NOT EXISTS(SELECT 1 FROM {$h['submissions']} s WHERE s.task_id=a.id AND s.student_id=%d) OR (SELECT s.status FROM {$h['submissions']} s WHERE s.task_id=a.id AND s.student_id=%d ORDER BY s.id DESC LIMIT 1)='revision')",$class->id,$year,$uid,$uid)):0;
 $out='<div class="dsp-school dsp-student-dashboard">'.dgs_school_title('پیشخوان دانش‌آموز').'<section class="dsp-welcome"><span class="dsp-cap">'.dgs_school_icon('cap').'</span><div><h2>سلام '.esc_html($u->display_name).' عزیز!</h2><p>به پیشخوان خود در مدرسه دانشگران خوش آمدید.</p></div>'.dgs_school_art().'</section><div class="dsp-stats dsp-three">'.dgs_school_stat('معدل کل',dgs_school_number($average,2),'آخرین گزارش منتشرشده','chart').dgs_school_stat('رتبه در پایه',dgs_school_number($rank),'بر اساس آخرین ماه گزارش','medal').dgs_school_stat('تکالیف در انتظار',dgs_fa_digits($pending),'مورد','check').'</div><div class="dsp-grid-two"><section class="dsp-card"><h3>'.dgs_school_icon('check').' آزمون‌های پیش رو</h3>';
 $events=$class?dgs_school_upcoming($class->id,$year,3):array();foreach($events as $event)$out.='<a class="dsp-event" href="'.esc_url(dgs_school_url('timetable',$year)).'"><span>'.dgs_school_icon('book').'</span><div><strong>'.esc_html($event['title']).'</strong><small>'.esc_html(dgs_quiz_fmt($event['at'])).'</small></div></a>';if(!$events)$out.='<p class="dsp-empty">آزمون آینده‌ای برای کلاس شما ثبت نشده است.</p>';
 $out.='</section><section class="dsp-card"><h3>'.dgs_school_icon('chart').' روند معدل (سه نوبت اخیر)</h3>'.dgs_school_line_chart($series).'</section></div><section class="dsp-card"><div class="dsp-section-head"><h3>'.dgs_school_icon('calendar').' برنامه هفتگی (پیش‌نمایش)</h3><a class="dg-btn" href="'.esc_url(dgs_school_url('timetable',$year)).'">مشاهده برنامه کامل ‹</a></div>'.($class?dgs_school_timetable_grid($class,true):'<p class="dsp-empty">هنوز کلاس تعیین نشده است.</p>').'</section><div class="dsp-grid-two"><section class="dsp-card"><h3>'.dgs_school_icon('bell').' اطلاعیه‌ها</h3>';
 $posts=get_posts(array('post_type'=>'post','post_status'=>'publish','numberposts'=>3));foreach($posts as $post)$out.='<a class="dsp-event" href="'.esc_url(get_permalink($post)).'"><span>'.dgs_school_icon('bell').'</span><div><strong>'.esc_html(get_the_title($post)).'</strong><small>'.esc_html(dgs_att_jdate(get_the_date('Y-m-d',$post))).'</small></div></a>';if(!$posts)$out.='<p class="dsp-empty">اطلاعیه‌ای منتشر نشده است.</p>';$out.='</section><section class="dsp-card"><h3>'.dgs_school_icon('coin').' وضعیت شهریه</h3>';
 $account=dgs_fin_get($uid,$year);if($account){$paid=dgs_fin_paid($account);$balance=(int)$account->tuition-(int)$account->discount-$paid;$out.='<div class="dsp-fee-balance"><span>'.dgs_school_icon('coin').'</span><div><small>مبلغ باقی‌مانده</small><strong>'.esc_html(dgs_fin_format($balance)).' <small>تومان</small></strong></div></div>';$ft=dgs_fin_tables();$installments=$wpdb->get_results($wpdb->prepare("SELECT due_on,amount FROM {$ft['installments']} WHERE account_id=%d ORDER BY due_on,id",$account->id));$due=null;foreach($installments as $part){if($paid<(int)$part->amount){$due=$part->due_on;break;}$paid-=(int)$part->amount;}if($due)$out.='<p class="dsp-due">'.dgs_school_icon('calendar').' مهلت پرداخت: '.esc_html(dgs_fa_digits(dgs_att_jdate($due))).'</p>';}
 else $out.='<p class="dsp-empty">شهریه این سال هنوز تعیین نشده است.</p>';
 return $out.'<a class="dg-btn dsp-wide" href="'.esc_url(dgs_school_url('finance',$year)).'">پرداخت شهریه '.dgs_school_icon('coin').'</a><p class="dsp-footnote">پیگیری پرداخت از مدرسه؛ درگاه آنلاین هنوز متصل نیست.</p></section></div></div>';
}
function dgs_school_timetable_grid($class,$preview=false){
 $plan=dgs_school_schedule($class->id);if(!$plan)return '<p class="dsp-empty">برنامه هفتگی این کلاس هنوز ثبت نشده است.</p>';$periods=json_decode($plan->periods,true);$cells=json_decode($plan->cells,true);$teaching=dgs_school_teaching($class->id);$map=array();foreach($cells as $c)$map[$c['day'].':'.$c['slot']]=$c;$days=array('شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه');$bells=array('اول','دوم','سوم','چهارم','پنجم','ششم');
 $cell=function($day,$slot)use($map,$teaching,$preview){$c=$map[$day.':'.$slot]??null;if(!$c)return '—';$lesson=$c['subject_id']?($teaching[$c['subject_id']]->title??'درس بایگانی‌شده'):$c['activity'];$teacher=$c['subject_id']?($teaching[$c['subject_id']]->teacher??''):(get_userdata($c['teacher_id'])->display_name??'');return '<strong>'.esc_html($lesson).'</strong>'.(!$preview&&$teacher?'<small>استاد '.esc_html($teacher).'</small>':'');};
 $out='<div class="dge-table-wrap dsp-timetable-wrap"><table class="dge-table dsp-timetable"><thead><tr>';if($preview){$out.='<th>زنگ</th>';for($d=0;$d<5;$d++)$out.='<th>'.$days[$d].'</th>';}
 else{$out.='<th>روز</th>';foreach($periods as $i=>$p)$out.='<th>زنگ '.$bells[$i].'<small dir="ltr">'.esc_html(dgs_fa_digits($p['start'].' – '.$p['end'])).'</small></th>';}$out.='</tr></thead><tbody>';
 if($preview){for($s=0;$s<3;$s++){$out.='<tr><th>زنگ '.dgs_fa_digits($s+1).'<small dir="ltr">'.esc_html(dgs_fa_digits($periods[$s]['start'].' – '.$periods[$s]['end'])).'</small></th>';for($d=0;$d<5;$d++)$out.='<td>'.$cell($d,$s).'</td>';$out.='</tr>';}}
 else for($d=0;$d<6;$d++){$out.='<tr><th>'.$days[$d].'</th>';for($s=0;$s<6;$s++)$out.='<td>'.$cell($d,$s).'</td>';$out.='</tr>';}
 return $out.'</tbody></table></div>';
}
function dgs_edu_view_timetable($year){return dgs_school_timetable_page($year);}
function dgs_school_timetable_page($year){
 $allowed=dgs_school_class_options($year);$selected=absint(dgs_att_get('school_class'));if(!$selected)$selected=(int)array_key_first($allowed);if(!$selected||!isset($allowed[$selected]))return '<div class="dsp-school">'.dgs_school_title('برنامه هفتگی کلاس').'<p class="dsp-empty">کلاس مجاز برای این سال تعیین نشده است.</p></div>';$class=$allowed[$selected];$out='<div class="dsp-school dsp-timetable-page">'.dgs_school_title('برنامه هفتگی کلاس','برنامه درسی هفتگی کلاس، همراه با زمان هر زنگ و نام استاد');
 if(count($allowed)>1||current_user_can('dgs_manage_education')){$options=array();foreach($allowed as $c)$options[$c->id]=dgs_edu_grade_label($c->grade).' — '.$c->title;$out.='<form class="dge-filter" method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="timetable"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('school_class','کلاس',$options,$selected).'<button class="dg-btn">نمایش</button></form>';}
 $out.='<div id="dsp-timetable-print"><section class="dsp-card dsp-class-strip"><div>'.dgs_school_icon('class').'<span>پایه<strong>'.esc_html(dgs_edu_grade_label($class->grade)).'</strong></span></div><div>'.dgs_school_icon('users').'<span>کلاس<strong>'.esc_html($class->title).'</strong></span></div><div>'.dgs_school_icon('calendar').'<span>سال تحصیلی<strong>'.esc_html(dgs_fa_digits($year)).'</strong></span></div><button type="button" class="dg-btn" data-school-print="dsp-timetable-print">چاپ برنامه ▤</button></section><section class="dsp-card">'.dgs_school_timetable_grid($class).'</section><section class="dsp-card"><h3>'.dgs_school_icon('calendar').' تقویم آزمون‌های پیش رو</h3><p class="dsp-subtitle">برنامه آزمون‌های کلاسی و امتحانات مدرسه در هفته‌های آینده</p>'.dgs_edu_table_start(array('ردیف','موضوع آزمون','درس','تاریخ برگزاری','ساعت','نوع آزمون'));$events=dgs_school_upcoming($class->id,$year);foreach($events as $i=>$event)$out.='<tr><td>'.esc_html(dgs_fa_digits($i+1)).'</td><td>'.esc_html($event['title']).'</td><td>'.esc_html($event['subject']).'</td><td>'.esc_html(dgs_fa_digits(dgs_att_jdate(wp_date('Y-m-d',$event['at'])))).'</td><td dir="ltr">'.esc_html(dgs_fa_digits(wp_date('H:i',$event['at']).' – '.$event['end'])).'</td><td><span class="dsp-tag '.($event['type']==='school'?'is-gold':'').'">'.($event['type']==='school'?'آزمون مدرسه':'آزمون کلاسی').'</span></td></tr>';
 $out.='</tbody></table></div>';if(!$events)$out.='<p class="dsp-empty">آزمون آینده‌ای ثبت نشده است.</p>';$out.='</section></div>';if(current_user_can('dgs_manage_education'))$out.=dgs_school_timetable_editor($class,$year);return $out.'</div>';
}
function dgs_school_timetable_editor($class,$year){
 $plan=dgs_school_schedule($class->id);$periods=$plan?json_decode($plan->periods,true):array(array('start'=>'07:30','end'=>'08:15'),array('start'=>'08:25','end'=>'09:10'),array('start'=>'09:20','end'=>'10:05'),array('start'=>'10:20','end'=>'11:05'),array('start'=>'11:15','end'=>'12:00'),array('start'=>'12:10','end'=>'12:55'));$map=array();if($plan)foreach(json_decode($plan->cells,true) as $c)$map[$c['day'].':'.$c['slot']]=$c;$events=$plan?json_decode($plan->events,true):array();$subjects=array();foreach(dgs_school_teaching($class->id) as $id=>$r)$subjects[$id]=$r->title;$teachers=dgs_edu_user_options('dgs_teacher');$out='<details class="dsp-card dsp-schedule-editor"><summary>ویرایش برنامه هفتگی و آزمون‌های حضوری</summary>'.dgs_school_form('schedule',$year).'<input type="hidden" name="class_id" value="'.(int)$class->id.'"><input type="hidden" name="revision" value="'.($plan?(int)$plan->revision:0).'"><h4>ساعت زنگ‌ها (۲۴ساعته)</h4><div class="dsp-bells">';foreach($periods as $i=>$p)$out.='<fieldset><legend>زنگ '.dgs_fa_digits($i+1).'</legend><label>شروع<input name="periods['.$i.'][start]" value="'.esc_attr($p['start']).'" dir="ltr" required></label><label>پایان<input name="periods['.$i.'][end]" value="'.esc_attr($p['end']).'" dir="ltr" required></label></fieldset>';$out.='</div><p class="dsp-footnote">درس باید به دبیر کلاس تخصیص یافته باشد. برای ورزش یا فعالیت ویژه می‌توانید درس را خالی گذاشته و عنوان فعالیت و دبیر را مشخص کنید.</p><div class="dge-table-wrap"><table class="dge-table dsp-edit-grid"><thead><tr><th>روز</th>';for($i=0;$i<6;$i++)$out.='<th>زنگ '.dgs_fa_digits($i+1).'</th>';$out.='</tr></thead><tbody>';$days=array('شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه');$index=0;
 foreach($days as $day=>$label){$out.='<tr><th>'.$label.'</th>';for($slot=0;$slot<6;$slot++){$c=$map[$day.':'.$slot]??array();$prefix='cells['.$index++.']';$out.='<td><input type="hidden" name="'.$prefix.'[day]" value="'.$day.'"><input type="hidden" name="'.$prefix.'[slot]" value="'.$slot.'">'.dgs_edu_select($prefix.'[subject_id]','درس',$subjects,$c['subject_id']??0,false).'<label>فعالیت<input name="'.$prefix.'[activity]" value="'.esc_attr($c['activity']??'').'" maxlength="100"></label>'.dgs_edu_select($prefix.'[teacher_id]','دبیر فعالیت',$teachers,$c['teacher_id']??0,false).'</td>';}$out.='</tr>';}$out.='</tbody></table></div><h4>تقویم آزمون حضوری کلاس / مدرسه</h4><div class="dge-table-wrap"><table class="dge-table"><thead><tr><th>عنوان</th><th>درس</th><th>تاریخ شمسی</th><th>شروع</th><th>پایان</th><th>نوع</th></tr></thead><tbody>';
 for($i=0;$i<10;$i++){$v=$events[$i]??array();$out.='<tr><td><input name="events['.$i.'][title]" value="'.esc_attr($v['title']??'').'" maxlength="150"></td><td>'.dgs_edu_select('events['.$i.'][subject_id]','درس',$subjects,$v['subject_id']??0,false).'</td><td><input name="events['.$i.'][date]" value="'.esc_attr(isset($v['at'])?dgs_att_jdate(wp_date('Y-m-d',$v['at'])):'').'" dir="ltr" placeholder="1405-09-01"></td><td><input name="events['.$i.'][time]" value="'.esc_attr(isset($v['at'])?wp_date('H:i',$v['at']):'').'" dir="ltr" placeholder="09:00"></td><td><input name="events['.$i.'][end]" value="'.esc_attr($v['end']??'').'" dir="ltr" placeholder="10:00"></td><td>'.dgs_edu_select('events['.$i.'][type]','نوع',array('class'=>'کلاسی','school'=>'مدرسه'),$v['type']??'class').'</td></tr>';}
 return $out.'</tbody></table></div><p class="dsp-footnote">ردیف با عنوان خالی حذف می‌شود. آزمون‌های آنلاین موجود خودکار به تقویم اضافه می‌شوند.</p><button class="dg-btn">ذخیره برنامه هفتگی</button></form></details>';
}
function dgs_school_manager_dashboard($year){
 if(!current_user_can('dgs_manage_education'))return '';global $wpdb;$e=dgs_edu_tables();$g=dgs_grade_table();$at=dgs_att_tables();$ft=dgs_fin_tables();$series=dgs_school_grade_series($year);$classes=dgs_edu_classes($year);$students=0;foreach($classes as $c)$students+=(int)$c->students_count;$teacher_count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT a.teacher_id) FROM {$e['teaching']} a JOIN {$e['classes']} c ON c.id=a.class_id WHERE c.school_year=%s AND c.active=1",$year));$default=substr(dgs_att_default_day($year),0,7);$period=dgs_grade_period(dgs_att_get('school_period',$default),$year)?:$default;$day=dgs_att_parse_day(dgs_att_get('school_day',dgs_att_default_day($year)),$year)?:dgs_att_parse_day(dgs_att_default_day($year),$year);
 $mean=$wpdb->get_var($wpdb->prepare("SELECT AVG(av) FROM (SELECT x.student_id,AVG(x.score) AS av FROM $g x JOIN {$e['classes']} c ON c.id=x.class_id WHERE c.school_year=%s AND x.period=%s AND x.published=1 GROUP BY x.student_id) averages",$year,$period));
 $totals=$wpdb->get_results($wpdb->prepare("SELECT r.status,COUNT(*) AS n FROM {$at['records']} r JOIN {$at['sessions']} s ON s.id=r.session_id JOIN {$e['classes']} c ON c.id=s.class_id WHERE c.school_year=%s AND s.school_day=%s AND s.closed=0 GROUP BY r.status",$year,$day));$attendance=array('present'=>0,'late'=>0,'absent'=>0);foreach($totals as $v)$attendance[$v->status]=(int)$v->n;$att_total=array_sum($attendance);$presence=$att_total?($attendance['present']+$attendance['late'])/$att_total*100:null;
 $expected=0;$recorded=0;$missing_grades=0;$missing_att=0;foreach($classes as $c){$subjects=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$e['teaching']} WHERE class_id=%d",$c->id));$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $g x WHERE x.class_id=%d AND x.period=%s AND EXISTS(SELECT 1 FROM {$e['enrollments']} en WHERE en.class_id=x.class_id AND en.student_id=x.student_id) AND EXISTS(SELECT 1 FROM {$e['teaching']} a WHERE a.class_id=x.class_id AND a.subject_id=x.subject_id)",$c->id,$period));$want=(int)$c->students_count*$subjects;$expected+=$want;$recorded+=$count;if($count<$want)$missing_grades++;$session=dgs_att_session($c->id,$day);if($c->students_count&&!$session)$missing_att++;}
 $completion=$expected?$recorded/$expected*100:null;$net=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(tuition-discount),0) FROM {$ft['accounts']} WHERE school_year=%s",$year));$paid=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(p.amount),0) FROM {$ft['payments']} p JOIN {$ft['accounts']} a ON a.id=p.account_id WHERE a.school_year=%s AND p.voided=0",$year));
 $request_counts=array('admission'=>0,'class'=>0,'counseling'=>0);$raw=$wpdb->get_col("SELECT d.meta_value FROM {$wpdb->posts} p JOIN {$wpdb->postmeta} d ON d.post_id=p.ID AND d.meta_key='_dgs_data' LEFT JOIN {$wpdb->postmeta} s ON s.post_id=p.ID AND s.meta_key='_dgs_status' WHERE p.post_type='dgs_request' AND p.post_status='private' AND (s.meta_value='new' OR s.meta_id IS NULL)");foreach($raw as $value){$d=maybe_unserialize($value);if(is_array($d)&&isset($request_counts[$d['type']??'']))$request_counts[$d['type']]++;}
 $out='<div class="dsp-school dsp-manager-dashboard">'.dgs_school_title('پیشخوان مدیر و معاون','نمای کلی وضعیت آموزشی، انضباطی، مالی و درخواست‌های مدرسه دانشگران').'<form method="get" class="dge-filter dsp-dashboard-filter" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="overview"><input type="hidden" name="dg_year" value="'.esc_attr($year).'" dir="ltr" required><label>ماه نمرات<input name="school_period" value="'.esc_attr($period).'" dir="ltr" required></label><label>تاریخ حضور و غیاب<input name="school_day" value="'.esc_attr(dgs_att_jdate($day)).'" dir="ltr" required></label><button class="dg-btn">نمایش</button></form><div class="dsp-stats dsp-four">'.dgs_school_stat('میانگین کل مدرسه',dgs_school_number($mean===null?null:(float)$mean,2),'نمرات منتشرشده ماه انتخابی','medal',true).dgs_school_stat('دانش‌آموزان',dgs_fa_digits($students),'نفر','users').dgs_school_stat('کلاس‌ها',dgs_fa_digits(count($classes)),'کلاس','class').dgs_school_stat('معلمان',dgs_fa_digits($teacher_count),'دبیر تخصیص‌یافته این سال','cap').'</div><div class="dsp-grid-three" id="dsp-school-statistics"><section class="dsp-card"><h3>'.dgs_school_icon('chart').' روند میانگین کل مدرسه</h3>'.dgs_school_line_chart($series).'</section><section class="dsp-card"><h3>'.dgs_school_icon('book').' وضعیت ارسال نمرات</h3><div class="dsp-ring-row">'.dgs_school_ring($completion,'ثبت شده','is-amber').'<div class="dsp-legend"><p>● ثبت شده: '.esc_html(dgs_school_number($completion,1)).'٪</p><p>● در انتظار: '.esc_html(dgs_school_number($completion===null?null:100-$completion,1)).'٪</p><small>'.esc_html(dgs_fa_digits($missing_grades)).' کلاس ناقص</small></div></div><p class="dsp-footnote">ماه '.esc_html(dgs_fa_digits($period)).'؛ نمره ثبت‌شده شامل پیش‌نویس دبیر نیز هست.</p></section><section class="dsp-card"><h3>'.dgs_school_icon('calendar').' نمای کلی حضور و غیاب</h3><div class="dsp-ring-row">'.dgs_school_ring($presence,'حضور').'<div class="dsp-legend"><p>● حضور: '.esc_html(dgs_school_number($presence,1)).'٪</p><p>غیبت موجه: —</p><p>غیبت غیرموجه: —</p></div></div><p class="dsp-footnote">'.esc_html(dgs_fa_digits($attendance['absent'])).' غیبت ثبت شده؛ تفکیک موجه/غیرموجه در اطلاعات فعلی ثبت نمی‌شود. روزهای ثبت‌نشده در درصد نیستند.</p></section></div><div class="dsp-grid-two"><section class="dsp-card"><h3>⚡ دسترسی سریع</h3><div class="dsp-quick-grid">';
 foreach(array(array('education','ثبت‌نام جدید','users','sd_add'=>'1'),array('education','مدیریت کلاس‌ها','class','school_section'=>'classes'),array('grades','ثبت نمرات','book'),array('attendance','ثبت غیبت گروهی','calendar'),array('requests','پیگیری درخواست‌ها','check'),array('overview','گزارش‌های مدیریتی','chart')) as $quick){$args=array();foreach($quick as $key=>$value)if(is_string($key))$args[$key]=$value;$href=dgs_school_url($quick[0],$year,$args);if($quick[1]==='گزارش‌های مدیریتی')$href.='#dsp-school-statistics';$out.='<a href="'.esc_url($href).'">'.dgs_school_icon($quick[2]).'<span>'.$quick[1].'</span></a>';}
 $out.='</div></section><section class="dsp-card"><h3>'.dgs_school_icon('coin').' وضعیت مالی شهریه مدرسه</h3><div class="dsp-finance-halves"><div><small>مبلغ وصول شده</small><strong>'.esc_html(dgs_fin_format($paid*10)).'</strong><span>ریال</span></div><div><small>مانده وصول نشده</small><strong>'.esc_html(dgs_fin_format(($net-$paid)*10)).'</strong><span>ریال</span></div></div><a class="dsp-finance-total" href="'.esc_url(dgs_school_url('finance',$year)).'">جمع کل شهریه سال تحصیلی: <strong>'.esc_html(dgs_fin_format($net*10)).'</strong> ریال</a><p class="dsp-footnote">با احتساب تخفیف؛ دفتر مالی به تومان ذخیره می‌شود و اینجا برای تطبیق طرح به ریال نمایش داده شده است.</p></section></div><div class="dsp-grid-two"><section class="dsp-card"><h3>'.dgs_school_icon('check').' درخواست‌های جدید</h3>';
 foreach(array('admission'=>'درخواست ثبت‌نام (پذیرش جدید)','class'=>'درخواست پیش‌ثبت‌نام کلاس‌ها','counseling'=>'درخواست مشاوره تحصیلی') as $type=>$label)$out.='<a class="dsp-request-row" href="'.esc_url(dgs_school_url('requests',$year)).'"><span>'.esc_html($label).'</span><strong>'.esc_html(dgs_fa_digits($request_counts[$type])).'</strong></a>';
 $out.='</section><section class="dsp-card"><h3>'.dgs_school_icon('bell').' هشدارها و موارد پیگیری</h3><div class="dsp-warning is-rose"><div><strong>غیبت‌های ثبت‌نشده</strong><p>برای '.esc_html(dgs_fa_digits($missing_att)).' کلاس فعال در تاریخ انتخاب‌شده رکوردی ثبت نشده است.</p></div><a href="'.esc_url(dgs_school_url('attendance',$year,array('att_day'=>dgs_att_jdate($day)))).'">مشاهده و پیگیری</a></div><div class="dsp-warning"><div><strong>ارسال نشدن نمرات</strong><p>نمرات '.esc_html(dgs_fa_digits($missing_grades)).' کلاس در ماه انتخاب‌شده کامل نیست.</p></div><a href="'.esc_url(dgs_school_url('grades',$year,array('grade_period'=>$period))).'">مشاهده و پیگیری</a></div></section></div></div>';return $out;
}
function dgs_edu_view_requests($year){if(!current_user_can('dgs_manage_education'))return '';return '<div class="dsp-school">'.dgs_school_title('پیگیری درخواست‌ها').'<section class="dsp-card"><p>برای بررسی اطلاعات درخواست و تغییر وضعیت، فهرست امن درخواست‌های وردپرس را باز کنید.</p><a class="dg-btn" href="'.esc_url(admin_url('edit.php?post_type=dgs_request')).'">باز کردن درخواست‌های دریافتی</a></section></div>';}
function dgs_school_page_active(){if(!dgs_is_role_portal())return false;if(function_exists('dgs_study_page_active')&&dgs_study_page_active())return true;$tab=dgs_portal_tab();return ($tab==='overview'&&(current_user_can('dgs_manage_education')||dgs_edu_role(get_current_user_id(),'dgs_student')))||in_array($tab,array('education','timetable','requests','records'),true);}
add_filter('body_class',function($classes){if(dgs_school_page_active())$classes[]='dgs-school-panels';return $classes;});
add_action('wp_enqueue_scripts',function(){if(!dgs_school_page_active())return;wp_register_style('dgs-school-panels',false,array(),DGS_VERSION);wp_enqueue_style('dgs-school-panels');wp_add_inline_style('dgs-school-panels',file_get_contents(DGS_PATH.'assets/school-panels.css'));wp_register_script('dgs-school-panels',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-school-panels');wp_add_inline_script('dgs-school-panels',file_get_contents(DGS_PATH.'assets/school-panels.js'));});
